column19:
SELECT DISTINCT
    s.symbol            AS ma_ck
FROM JAD_STOCKINFOR s
WHERE s.FloorCode IN ('10','02','04', ' 03')   -- HOSE, HNX, UPCOM
   AND  NOT  (
    (s.floorcode = '02'  AND s.stocktype  in (1,4)
    OR
    (s.floorcode = '10' AND s.stocktype = 1
);
  AND s.tradingdate = :ngay_gd;

